// ============================================================
// 365 DAILY QUOTES — one for each day of the year, in 5 languages
//
// Quote 1 shows on 1 January, quote 2 on 2 January … quote 365 on 31 December.
// (In a leap year, 31 December shows quote 1 again.)
//
// HOW TO CHANGE A QUOTE
//   Find the day (e.g. "Day 45 · 14 February") and edit the text in quotes.
//   en = English, ta = Tamil, ml = Malayalam, te = Telugu, hi = Hindi
//   Use “ ” or ‘ ’ inside a quote — never the straight " character.
//
// HOW TO ADD A NEW AUTHOR
//   Add them to AUTHORS below with their name in all 5 languages,
//   then use  author: A.theirName  in the quote.
//
// Where a quote was first written in Tamil, Hindi, Malayalam or Telugu
// (Thirukkural, Avvaiyar, Bharathiyar, Kabir, proverbs…), that language
// shows the original words; the others show the meaning.
//
// Please ask native speakers to check the translations before launch.
// ============================================================

